fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // Calculate the absolute difference
    let diff = (a - b).abs();
    // Check if the difference is strictly less than the tolerance
    diff < tol
}

fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    // Ensure the input arrays are of equal length and the tolerance is positive
    assert!(a.len() == b.len() && !a.is_empty(), "Input arrays must be of equal non-zero length.");
    assert!(tol > 0, "Tolerance must be strictly positive.");

    // Create a result vector of booleans
    let mut result = Vec::with_capacity(a.len());

    // Iterate through the elements of both arrays
    for (&x, &y) in a.iter().zip(b.iter()) {
        // Use the is_close_i8 function to determine closeness
        result.push(is_close_i8(x, y, tol));
    }

    result
}